<script setup lang="ts">
import { ref } from 'vue';
import { api } from '../platform';
import { type Row } from '../../../shared/domain';
import { useWeather, weatherText, weatherSymbol, defaultCity, hometownCity } from '../../../shared/weather';
const { city, weather, cities, search, error, loading, searching, current, days, load, find } = useWeather(api);
const expanded = ref(false), choosing = ref(false), locating = ref(false);
function choose(row: Row) { choosing.value = false;load(row); }
function locate() { locating.value = true;error.value = '';uni.getLocation({ type: 'wgs84', isHighAccuracy: false, success: position => choose({ name: '当前位置', latitude: position.latitude, longitude: position.longitude }), fail: () => { error.value = '未能获取位置，请检查定位授权或手动选择城市。'; }, complete: () => { locating.value = false; } }); }
</script>
<template><view class="mobile-weather"><view class="weather-top"><view @click="choosing = !choosing"><text class="weather-place">⌖ {{ city.name }} ⌄</text><view class="weather-caption">出门前，看一眼天气</view></view><view v-if="weather" class="weather-summary" @click="expanded = !expanded"><text class="weather-degree">{{ Math.round(current.temperature_2m) }}°</text><view><text class="weather-icon">{{ weatherSymbol(current.weather_code, !!current.is_day) }}</text><text class="weather-state">{{ weatherText(current.weather_code) }}</text></view><text class="weather-expand">{{ expanded ? '⌃' : '⌄' }}</text></view><text v-else class="weather-caption">{{ loading ? '天气加载中…' : '暂未获取天气' }}</text></view><view v-if="weather" class="weather-caption">天气数据：Open-Meteo</view><view v-if="expanded && weather"><view class="weather-days"><view v-for="day in days" :key="day.date"><text>{{ day.label }}</text><text class="day-symbol">{{ weatherSymbol(day.code) }}</text><text>{{ Math.round(day.low) }}° / {{ Math.round(day.high) }}°</text></view></view><view class="weather-caption">体感 {{ current.apparent_temperature }}° · 湿度 {{ current.relative_humidity_2m }}% · 风速 {{ current.wind_speed_10m }} km/h</view><view class="weather-caption">{{ current.time?.replace('T', ' ') }} · 北京时间 · Open-Meteo</view></view><view v-if="error" class="weather-error">{{ error }}<button class="text-button" @click="load()">重新获取</button></view><view v-if="choosing" class="weather-picker"><view class="button-row"><button class="small" @click="choose(defaultCity)">苏州</button><button class="small" @click="choose(hometownCity)">沭阳</button><button class="small" :disabled="locating" @click="locate">{{ locating ? '定位中…' : '使用我的位置' }}</button></view><view class="safe-note">仅用于天气查询，不写入会员资料。定位需要你的授权。</view><view class="row"><input v-model="search" placeholder="输入城市名或拼音" maxlength="40"/><button class="small" :disabled="searching" @click="find">搜索</button></view><view v-for="row in cities" :key="row.id" class="weather-city" @click="choose(row)">{{ row.name }} · {{ row.admin1 }} · {{ row.country }}</view></view></view></template>
